	}
	for _, id := range discoveredIDs {
		if id == "" {
			continue
		}
		if _, exists := out[id]; exists {
			continue
		}
		if length, source := resolveContextEvidence(ctx, pcfg, id, cat); length > 0 {
			out[id] = length
			sources[id] = source
		}
	}
	if len(out) == 0 {
		return nil, nil
	}
	return out, sources
